package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored edit in the audit file; the person's own terms whenever the edit gives them (blank: cleared),
 *  and likewise their contact. */
public class AuditPersonEdited {
    public void audit(@Val PersonRequest request, @Val Person loaded, @Val PersonResponse saved, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + loaded.sheetId() + " by=" + request.user()
                + " name=" + saved.name() + " grade=" + saved.grade()
                + (request.terms() != null ? " terms=" + request.terms() : "")
                + (request.contact() != null ? " contact=" + request.contact() : ""));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Give each selected person the grade from the from-date (the sheet's today when none was given), in list order
 *  (the order they were added), exactly as the person form's edit would: a new version, the grade recorded from
 *  the date keeping those from other dates, name and terms kept, its PERSON_EDITED line and then how the sheet's
 *  figures moved over it. A selected id not on the sheet is skipped. A viewer's bulk grade changes nobody and writes
 *  nothing. */
public class BulkGradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGradeInput input, PersonRepository people,
            SheetRepository sheets, RoleRepository roles, Rollups rollups, Audit audit, Out<BulkGradeResponse> result) {
        String sheet = sheetId.trim();
        if (Role.VIEWER.equals(roles.of(sheet, input.user()))) {
            result.set(new BulkGradeResponse(0));
            return;
        }
        LocalDate from = input.from() != null ? input.from() : sheets.today(sheet);
        int changed = 0;
        for (Person loaded : people.list(sheet)) {
            if (!input.personIds().contains(loaded.id())) {
                continue;
            }
            Rollup before = rollups.take(sheet);
            Person person = new Person(loaded.id(), loaded.sheetId(), loaded.name(), loaded.grade(),
                    loaded.version() + 1, loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(),
                    loaded.retiredFrom(), loaded.grades(), loaded.holds(), loaded.terms(), loaded.contact(), loaded.aliases());
            if (!people.update(person, loaded.version())) {
                continue;
            }
            people.grade(person, input.grade(), from);
            PersonResponse saved = PersonResponse.from(people.find(sheet, loaded.id()));
            audit.record("PERSON_EDITED sheet=" + sheet + " by=" + input.user()
                    + " name=" + saved.name() + " grade=" + saved.grade());
            rollups.record(sheet, input.user(), before);
            changed++;
        }
        result.set(new BulkGradeResponse(changed));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded person and store it, refused when the person has been saved since
 *  the version the edit was made from. The grade is recorded from the edit's from-date (the sheet's today
 *  when none was given), keeping the grades already recorded from other dates. The person's own terms are set when the edit gives
 *  them (cleared when given blank), and so is their contact. */
public class SavePerson {
    public void save(@Val PersonRequest request, @Val Person loaded, PersonRepository repository,
            SheetRepository sheets, Out<PersonResponse> saved) throws StalePersonException {
        long from = request.version() == null ? loaded.version() : request.version();
        Person person = new Person(loaded.id(), loaded.sheetId(), request.name(), loaded.grade(), from + 1,
                loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(), loaded.retiredFrom(),
                loaded.grades(), loaded.holds(), loaded.terms(), loaded.contact(), loaded.aliases());
        if (!repository.update(person, from)) {
            throw new StalePersonException(loaded.name());
        }
        LocalDate gradeFrom = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom())
                : sheets.today(loaded.sheetId());
        repository.grade(person, request.grade(), gradeFrom);
        if (request.terms() != null) {
            repository.terms(person, request.terms().isEmpty() ? null : Integer.valueOf(request.terms()));
        }
        if (request.contact() != null) {
            repository.contact(person, request.contact().isEmpty() ? null : request.contact());
        }
        saved.set(PersonResponse.from(repository.find(loaded.sheetId(), loaded.id())));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;

/** A person's dated grades, earliest first: each applies from its from-date (null: from the beginning of time). */
public record Grades(List<Grade> history) {

    /** A grade given from a from-date (null: from the beginning of time). */
    public record Grade(String grade, LocalDate from) {
        boolean appliesOn(LocalDate date) {
            return from == null || !from.isAfter(date);
        }
    }

    public static final Grades NONE = new Grades(List.of());

    /** The grade in force on the date: the one whose from-date is the latest on or before it; "" when none applies. */
    public String on(LocalDate date) {
        return history.stream().filter(g -> g.appliesOn(date))
                .max(Comparator.comparing(Grade::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(Grade::grade).orElse("");
    }
}
package net.officefloor.hq.app.person;

/** A person add or edit to a name another person on the sheet, or on another sheet of its tree, already has. */
public class DuplicatePersonNameException extends Exception {
    public DuplicatePersonNameException(String name) {
        super("The name " + name + " is already in use on this sheet.");
    }

    /** The name is already a name or alias on another sheet of this sheet's tree. */
    public DuplicatePersonNameException(String name, String sheetId) {
        super("The name " + name + " is already in use on sheet " + sheetId + ", in this sheet's tree.");
    }

    /** Refuse the name when another sheet of the sheet's tree already has it as a name or an alias. */
    public static void refuseInTree(String sheetId, String name, PersonRepository repository)
            throws DuplicatePersonNameException {
        String other = repository.sheetInTreeUsing(sheetId, name);
        if (other != null) {
            throw new DuplicatePersonNameException(name, other);
        }
    }
}
